{"file_path":"src/lexer.js","content":"/**
 * Scans UTF-8 source text into a flat array of tokens, or throws a
 * `LexError` at the first position where the input does not scan.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

function isDigit(c) {
  return c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return isDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isBinDigit(c) {
  return c === '0' || c === '1'
}

function isOctDigit(c) {
  return c >= '0' && c <= '7'
}

function isLetter(c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
}

function isIdentStart(c) {
  return isLetter(c) || c === '_'
}

function isIdentChar(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

function isGarbageChar(c) {
  return isLetter(c) || isDigit(c) || c === '_'
}

/** An error at a specific line/column, carrying the message's reason text. */
export class LexError extends Error {
  constructor(pos, reason) {
    super(`${pos.line}:${pos.col}: ${reason}`)
    this.line = pos.line
    this.col = pos.col
    this.reason = reason
  }
}

class Cursor {
  constructor(source) {
    this.chars = Array.from(source)
    this.i = 0
    this.line = 1
    this.col = 1
  }

  peek(offset = 0) {
    return this.chars[this.i + offset]
  }

  pos() {
    return { line: this.line, col: this.col }
  }

  advance() {
    const c = this.chars[this.i]
    this.i++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col++
    }
    return c
  }
}

function consumeDigitRun(cur, charTest) {
  let added = ''
  let digits = 0
  let lastWasDigit = false
  while (true) {
    const c = cur.peek()
    if (c !== undefined && charTest(c)) {
      added += cur.advance()
      digits++
      lastWasDigit = true
    } else if (c === '_' && lastWasDigit && cur.peek(1) !== undefined && charTest(cur.peek(1))) {
      added += cur.advance()
      lastWasDigit = false
    } else {
      break
    }
  }
  return [added, digits]
}

function consumeGarbage(cur) {
  let added = ''
  while (cur.peek() !== undefined && isGarbageChar(cur.peek())) {
    added += cur.advance()
  }
  return added
}

function skipLineComment(cur) {
  while (cur.peek() !== undefined && cur.peek() !== '\n') {
    cur.advance()
  }
}

function skipBlockComment(cur) {
  const startPos = cur.pos()
  cur.advance()
  cur.advance()
  let depth = 1
  while (depth > 0) {
    if (cur.peek() === undefined) {
      throw new LexError(startPos, 'unterminated block comment')
    }
    if (cur.peek() === '/' && cur.peek(1) === '*') {
      cur.advance()
      cur.advance()
      depth++
    } else if (cur.peek() === '*' && cur.peek(1) === '/') {
      cur.advance()
      cur.advance()
      depth--
    } else {
      cur.advance()
    }
  }
}

function skipTrivia(cur) {
  while (true) {
    const c = cur.peek()
    if (c === undefined) return
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      cur.advance()
      continue
    }
    if (c === '/' && cur.peek(1) === '/') {
      skipLineComment(cur)
      continue
    }
    if (c === '/' && cur.peek(1) === '*') {
      skipBlockComment(cur)
      continue
    }
    return
  }
}

function scanIdent(cur) {
  const startPos = cur.pos()
  let text = ''
  while (cur.peek() !== undefined && isIdentChar(cur.peek())) {
    text += cur.advance()
  }
  const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
  return { kind, text, line: startPos.line, col: startPos.col }
}

function scanNumber(cur) {
  const startPos = cur.pos()
  let text = ''
  const c0 = cur.advance()
  text += c0

  if (c0 === '0' && cur.peek() !== undefined && 'xXbBoO'.includes(cur.peek())) {
    const p = cur.advance()
    text += p
    let charTest
    if (p === 'x' || p === 'X') charTest = isHexDigit
    else if (p === 'b' || p === 'B') charTest = isBinDigit
    else charTest = isOctDigit

    const [added, digits] = consumeDigitRun(cur, charTest)
    text += added
    if (digits === 0) {
      text += consumeGarbage(cur)
      throw new LexError(startPos, `invalid number ${text}`)
    }
  } else {
    const [added] = consumeDigitRun(cur, isDigit)
    text += added

    if (cur.peek() === '.' && isDigit(cur.peek(1))) {
      text += cur.advance()
      const [added2] = consumeDigitRun(cur, isDigit)
      text += added2
    }

    if (
      (cur.peek() === 'e' || cur.peek() === 'E') &&
      (isDigit(cur.peek(1)) || ((cur.peek(1) === '+' || cur.peek(1) === '-') && isDigit(cur.peek(2))))
    ) {
      text += cur.advance()
      if (cur.peek() === '+' || cur.peek() === '-') text += cur.advance()
      const [added3] = consumeDigitRun(cur, isDigit)
      text += added3
    }
  }

  if (cur.peek() !== undefined && isGarbageChar(cur.peek())) {
    text += consumeGarbage(cur)
    throw new LexError(startPos, `invalid number ${text}`)
  }

  return { kind: 'number', text, line: startPos.line, col: startPos.col }
}

function readEscape(cur, escapePos) {
  const esc = cur.peek()
  if (esc === 'n') {
    cur.advance()
    return '\n'
  }
  if (esc === 't') {
    cur.advance()
    return '\t'
  }
  if (esc === 'r') {
    cur.advance()
    return '\r'
  }
  if (esc === '\\') {
    cur.advance()
    return '\\'
  }
  if (esc === '"') {
    cur.advance()
    return '"'
  }
  if (esc === '0') {
    cur.advance()
    return '\0'
  }
  if (esc === 'x') {
    cur.advance()
    const h1 = cur.peek()
    const h2 = cur.peek(1)
    if (h1 !== undefined && isHexDigit(h1) && h2 !== undefined && isHexDigit(h2)) {
      cur.advance()
      cur.advance()
      return String.fromCharCode(parseInt(h1 + h2, 16))
    }
    throw new LexError(escapePos, 'invalid escape \\x')
  }
  if (esc === 'u') {
    cur.advance()
    if (cur.peek() !== '{') {
      throw new LexError(escapePos, 'invalid escape \\u')
    }
    cur.advance()
    let hex = ''
    while (cur.peek() !== undefined && isHexDigit(cur.peek())) {
      hex += cur.advance()
    }
    if (hex.length === 0 || cur.peek() !== '}') {
      throw new LexError(escapePos, 'invalid escape \\u')
    }
    cur.advance()
    const codePoint = parseInt(hex, 16)
    if (codePoint > 0x10ffff) {
      throw new LexError(escapePos, 'invalid escape \\u')
    }
    return String.fromCodePoint(codePoint)
  }
  throw new LexError(escapePos, `invalid escape \\${esc === undefined ? '' : esc}`)
}

function scanString(cur) {
  const startPos = cur.pos()
  cur.advance()
  let value = ''
  while (true) {
    const c = cur.peek()
    if (c === undefined) {
      throw new LexError(startPos, 'unterminated string')
    }
    if (c === '\n') {
      throw new LexError(cur.pos(), 'newline in string')
    }
    if (c === '"') {
      cur.advance()
      break
    }
    if (c === '\\') {
      const escapePos = cur.pos()
      cur.advance()
      if (cur.peek() === undefined) {
        continue
      }
      value += readEscape(cur, escapePos)
      continue
    }
    value += cur.advance()
  }
  return { kind: 'string', text: value, value, line: startPos.line, col: startPos.col }
}

function scanRawString(cur) {
  const startPos = cur.pos()
  cur.advance()
  cur.advance()
  let value = ''
  while (true) {
    const c = cur.peek()
    if (c === undefined) {
      throw new LexError(startPos, 'unterminated string')
    }
    if (c === '"') {
      cur.advance()
      break
    }
    value += cur.advance()
  }
  return { kind: 'rawstring', text: value, value, line: startPos.line, col: startPos.col }
}

function scanPunct(cur) {
  const startPos = cur.pos()
  const two = (cur.peek() ?? '') + (cur.peek(1) ?? '')
  if (TWO_CHAR_PUNCT.includes(two)) {
    cur.advance()
    cur.advance()
    return { kind: 'punct', text: two, line: startPos.line, col: startPos.col }
  }
  const one = cur.peek()
  if (ONE_CHAR_PUNCT.has(one)) {
    cur.advance()
    return { kind: 'punct', text: one, line: startPos.line, col: startPos.col }
  }
  throw new LexError(startPos, `unexpected character ${one}`)
}

/** Scans `source` into an array of tokens, throwing `LexError` on failure. */
export function tokenize(source) {
  const cur = new Cursor(source)
  const tokens = []
  while (true) {
    skipTrivia(cur)
    const c = cur.peek()
    if (c === undefined) break

    if (c === 'r' && cur.peek(1) === '"') {
      tokens.push(scanRawString(cur))
      continue
    }
    if (isIdentStart(c)) {
      tokens.push(scanIdent(cur))
      continue
    }
    if (isDigit(c)) {
      tokens.push(scanNumber(cur))
      continue
    }
    if (c === '"') {
      tokens.push(scanString(cur))
      continue
    }
    tokens.push(scanPunct(cur))
  }
  return tokens
}
"}

